CREATE TABLE IF NOT EXISTS yhn_visit_cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), member_id TEXT NOT NULL, case_code TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending_verification' CHECK (status IN ('pending_verification','verified')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(member_id,case_code))